      ShapeElement(xEmu: 736600.0, yEmu: 1930400.0, cxEmu: 6400800.0, cyEmu: 4572000.0, zOrder: 2009, shapeId: 32, commandText: '{Arduino}', presetGeometry: 'rect', fill: NoFill(), paragraphs: [TextParagraph(runs: [TextRun(text: '#include <Wire.h>\r\nconst byte MPU = 0x68;\r\n\r\nvoid setup() {\r\n  Wire.begin(21, 22);\r\n  Serial.begin(115200);\r\n  // Acorda o sensor (registrador PWR_MGMT_1)\r\n  Wire.beginTransmission(MPU);\r\n  Wire.write(0x6B);\r\n  Wire.write(0x00);\r\n  Wire.endTransmission();\r\n}\r\n\r\nvoid loop() {\r\n  Wire.beginTransmission(MPU);\r\n  Wire.write(0x3B);       // ACCEL_XOUT_H\r\n  Wire.endTransmission(false);\r\n  Wire.requestFrom(MPU, 6);\r\n  int16_t ax = Wire.read()<<8 | Wire.read();\r\n  int16_t ay = Wire.read()<<8 | Wire.read();\r\n  int16_t az = Wire.read()<<8 | Wire.read();\r\n  Serial.printf("X=%d Y=%d Z=%d\\n", ax, ay, az);\r\n  delay(100);\r\n}', props: RunProperties(fontSizePt: 13.0, kerningPt: 12.0, color: Color(0xFFE2E8F0), fontFamily: 'Consolas', isPlaceholder: true))], props: ParagraphProperties(marLeftEmu: 0.0))], bodyProps: TextBodyProperties(), altText: 'CaixaDeTexto 10'),
